package com.youngone.mediacontrol.identity.domain;
import com.youngone.mediacontrol.identity.integration.SyncMode;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="hr_sync_runs")public class HrSyncRun{@Id private UUID id;@Column(name="source_id",nullable=false)private UUID sourceId;@Enumerated(EnumType.STRING)@Column(name="sync_mode",nullable=false,length=20)private SyncMode syncMode;@Column(nullable=false,length=20)private String status;@Column(name="read_count",nullable=false)private long readCount;@Column(name="applied_count",nullable=false)private long appliedCount;@Column(name="conflict_count",nullable=false)private long conflictCount;@Column(name="started_at",nullable=false)private Instant startedAt;@Column(name="ended_at")private Instant endedAt;@Column(name="initiated_by",nullable=false,length=100)private String initiatedBy;@Column(name="file_hash",length=64)private String fileHash;@Column(name="dry_run",nullable=false)private boolean dryRun;protected HrSyncRun(){}public HrSyncRun(UUID sourceId,SyncMode mode,long read,long applied,long conflicts,String actor,String fileHash,boolean dryRun,Instant started,Instant ended){id=UUID.randomUUID();this.sourceId=sourceId;syncMode=mode;status=dryRun?"DRY_RUN":conflicts==0?"COMPLETED":"COMPLETED_WITH_CONFLICTS";readCount=read;appliedCount=applied;conflictCount=conflicts;startedAt=started;endedAt=ended;initiatedBy=actor;this.fileHash=fileHash;this.dryRun=dryRun;}public UUID getId(){return id;}}